<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; class Booking extends Model { protected $fillable=['trip_id','passenger_user_id','booking_reference','seat_numbers','passenger_count','subtotal','discount','total','payment_status','status']; protected $casts=['seat_numbers'=>'array','subtotal'=>'decimal:2','discount'=>'decimal:2','total'=>'decimal:2']; public function trip(){return $this->belongsTo(Trip::class);} public function passenger(){return $this->belongsTo(User::class,'passenger_user_id');} public function payment(){return $this->hasOne(Payment::class);} }